const fs = require('fs');

function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const N = readInt();
    if (N === null) return;
    const K = readInt();
    const C = readInt();

    const A = new Int32Array(N);
    let totalSum = 0;
    for (let i = 0; i < N; i++) {
        A[i] = readInt();
        totalSum += A[i];
    }

    if (K * C === N) {
        console.log(0);
        return;
    }

    if (C === 1) {
        // Ordena para pegar os K menores elementos
        A.sort();
        let coveredSum = 0;
        for (let i = 0; i < K; i++) {
            coveredSum += A[i];
        }
        console.log(totalSum - coveredSum);
        return;
    }

    // Prefixo de somas para obter soma de subsegmentos de tamanho C em O(1)
    const pref = new Int32Array(N + 1);
    for (let i = 0; i < N; i++) {
        pref[i + 1] = pref[i] + A[i];
    }

    // DP: queremos minimizar a soma coberta por K etiquetas
    // Como K * C <= N e C >= 2, temos K <= N / 2 <= 5000.
    // Usamos dois vetores para economizar memória
    let prev = new Int32Array(N + 1);
    let curr = new Int32Array(N + 1);

    for (let j = 1; j <= K; j++) {
        const minI = j * C;
        // Para i < minI, não é possível colocar j etiquetas
        // Então curr[minI - 1] não é acessado além do necessário
        let best = prev[minI - C] + (pref[minI] - pref[minI - C]);
        curr[minI] = best;

        for (let i = minI + 1; i <= N; i++) {
            const take = prev[i - C] + (pref[i] - pref[i - C]);
            if (take < best) {
                best = take;
            }
            curr[i] = best;
        }

        // Troca os buffers para a próxima iteração
        const temp = prev;
        prev = curr;
        curr = temp;
    }

    const minCovered = prev[N];
    console.log(totalSum - minCovered);
}

solve();
